     2118:             {
     2119:                 _TIFFfreeExt(tif, rb);
     2120:                 return (0);
     2121:             }
     2122:             if (sp->dctable[m] != 0)
     2123:                 _TIFFfreeExt(tif, sp->dctable[m]);
     2124:             sp->dctable[m] = rb;
     2125:             sp->sos_tda[m] = (m << 4);
     2126:         }
